def acyclic(graph):
    colors = {}

    def visit(node):
        color = colors.get(node, 0)
        if color == 1:
            return False
        if color == 2:
            return True
        colors[node] = 1
        for target in graph.get(node, ()):
            if not visit(target):
                return False
        colors[node] = 2
        return True

    nodes = set(graph)
    for targets in graph.values():
        nodes.update(targets)
    return all(visit(node) for node in nodes)
